import type { PlaceData } from './placeIndex';
import { EMPTY_PLACE_DATA, indexPlaces, type IndexedPlaces } from './placeIndex';
import { storeRepository } from '../repositories/storeRepository';

/**
 * Agra's local place data, loaded on first use (a few hundred KB of JSON is parsed only when a pin first needs a label, never at app
 * start). data/agraPlaces.json is generated by scripts/build-agra-places.mjs; data/agraPlaces.extra.json is the owner's own additions
 * (a colony, a lane, a landmark the maps do not know) and is merged in front, so an owner entry wins over a map entry of the same name.
 */
let cached: PlaceData | null = null;

export function loadPlaceData(): PlaceData {
  if (cached) return cached;
  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const generated = require('../../data/agraPlaces.json') as Partial<PlaceData>;
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const extra = require('../../data/agraPlaces.extra.json') as Partial<PlaceData>;
    cached = {
      localities: [...(extra.localities ?? []), ...(generated.localities ?? [])],
      streets: [...(extra.streets ?? []), ...(generated.streets ?? [])],
      landmarks: [...(extra.landmarks ?? []), ...(generated.landmarks ?? [])],
      pincodes: [...(extra.pincodes ?? []), ...(generated.pincodes ?? [])],
      postalAreas: [...(extra.postalAreas ?? []), ...(generated.postalAreas ?? [])],
    };
  } catch {
    cached = EMPTY_PLACE_DATA; // a missing data file must never break address entry
  }
  return cached;
}

export interface PlaceContext {
  places: IndexedPlaces;
  fallbackCity: string | null;
}

let contextPromise: { at: number; value: Promise<PlaceContext> } | null = null;
const CONTEXT_TTL_MS = 10 * 60_000;

/** The place index plus the app's own stores as anchors ("Vijay Nagar Colony, Agra" at the store's coordinates), refreshed every few minutes. */
export function getPlaceContext(): Promise<PlaceContext> {
  if (contextPromise && Date.now() - contextPromise.at < CONTEXT_TTL_MS) return contextPromise.value;
  const value = (async (): Promise<PlaceContext> => {
    const data = loadPlaceData();
    try {
      const stores = await storeRepository.list();
      return {
        places: indexPlaces(data, stores.map((s) => ({ addressLine: s.addressLine, lat: s.lat, lng: s.lng }))),
        fallbackCity: stores.find((s) => s.city)?.city ?? null,
      };
    } catch {
      // Offline or the stores could not be read: the map data alone still answers.
      return { places: indexPlaces(data, []), fallbackCity: null };
    }
  })();
  contextPromise = { at: Date.now(), value };
  return value;
}
